using NexaStation.Core;
using NexaStation.Domain;
using NexaStation.Gallery.Albums;
using NexaStation.Gallery.Navigation;
using NexaStation.Gallery.Slideshows;
using NexaStation.Gallery.Viewing;
using NexaStation.Infrastructure.Persistence;
using Xunit;

namespace NexaStation.Gallery.Tests;

public sealed class GalleryExperienceTests
{
    [Fact] public void NavigatorMovesPreviousAndNextWithWrap(){GalleryMediaItem[] items=[Item("a"),Item("b"),Item("c")];Assert.Equal("b",GalleryNavigator.Move(items,"a",1)!.Id);Assert.Equal("c",GalleryNavigator.Move(items,"a",-1)!.Id);}
    [Fact] public void NavigatorSkipsMissingAndVideoForImageViewer(){GalleryMediaItem[] items=[Item("a"),Item("missing") with{Available=false},Item("video") with{MediaType=GalleryMediaType.Video},Item("b")];Assert.Equal("b",GalleryNavigator.Move(items,"a",1)!.Id);}
    [Fact] public void FitViewportPreservesImageAndPanBounds(){GalleryViewport fit=GalleryViewportController.Create(1920,1080,4000,3000);Assert.Equal(0.36,fit.Scale,2);GalleryViewport panned=GalleryViewportController.Pan(GalleryViewportController.Zoom(fit,2),10000,-10000);Assert.InRange(panned.PanX,-960,960);Assert.InRange(panned.PanY,-540,540);}
    [Fact] public void ZoomIsClampedBetweenFitAndEightTimesFit(){GalleryViewport fit=GalleryViewportController.Create(1000,500,1000,1000);Assert.Equal(fit.Scale,GalleryViewportController.Zoom(fit,0.0001).Scale);Assert.Equal(fit.Scale*8,GalleryViewportController.Zoom(fit,1000).Scale);}
    [Fact] public void ResizeRecalculatesBoundsAndResetClearsPan(){GalleryViewport value=GalleryViewportController.Pan(GalleryViewportController.Zoom(GalleryViewportController.Create(800,600,1600,900),3),200,100);GalleryViewport resized=GalleryViewportController.Resize(value,400,300);Assert.Equal(0,resized.PanX);Assert.Equal(0,resized.PanY);}
    [Theory]
    [InlineData("\"{MEDIA_PATH}\"",1)]
    [InlineData("--fullscreen \"{MEDIA_PATH}\"",2)]
    public void MediaTemplatePreservesPathAsOneArgument(string template,int count){IReadOnlyList<string> args=MediaArgumentTemplate.Render(template,"C:\\My Videos\\clip.mp4");Assert.Equal(count,args.Count);Assert.Equal("C:\\My Videos\\clip.mp4",args[^1]);}
    [Theory]
    [InlineData("{MEDIA_PATH} & calc.exe")]
    [InlineData("{MEDIA_PATH} | more")]
    [InlineData("--file no-placeholder")]
    [InlineData("\"{MEDIA_PATH}")]
    public void MediaTemplateRejectsUnsafeOrMalformedInput(string template)=>Assert.Throws<InvalidOperationException>(()=>MediaArgumentTemplate.Render(template,"C:\\clip.mp4"));

    [Fact] public async Task SlideshowStartsAdvancesAndStops(){SlideshowService service=new();List<string> seen=[];service.ItemChanged+=(_,item)=>seen.Add(item.Id);await service.StartAsync(new([Item("a"),Item("b")],"a",1,Loop:true,Transition:GallerySlideshowTransition.None));Assert.True(service.State.Active);await Task.Delay(1200);Assert.Contains("b",seen);await service.StopAsync(GallerySlideshowStopReason.UserReturned);Assert.False(service.State.Active);service.Dispose();}
    [Fact] public async Task SlideshowPausesWhileFrontendLosesForeground(){SlideshowService service=new();await service.StartAsync(new([Item("a"),Item("b")],"a",1));service.SetForeground(false);await Task.Delay(1100);Assert.True(service.State.Paused);Assert.Equal("a",service.State.CurrentItemId);service.SetForeground(true);await service.StopAsync(GallerySlideshowStopReason.UserReturned);service.Dispose();}
    [Fact] public async Task SlideshowSkipsUnavailableAndVideos(){SlideshowService service=new();await service.StartAsync(new([Item("missing") with{Available=false},Item("video") with{MediaType=GalleryMediaType.Video},Item("image")],null));Assert.Equal("image",service.State.CurrentItemId);await service.StopAsync(GallerySlideshowStopReason.UserReturned);service.Dispose();}

    [Fact] public async Task AlbumsCreateRenameAddRemoveAndDeleteWithoutDeletingMedia(){await using TestDatabase db=await TestDatabase.CreateAsync();SqliteGalleryPersistence persistence=new(db.Factory);GalleryAlbumService albums=new(persistence);await SeedAsync(persistence);GalleryMediaItem media=(await persistence.QueryAsync(new())).Single();GalleryAlbum album=await albums.CreateAsync("Trip");await albums.AddAsync(album.Id,media.Id);Assert.Single(await persistence.QueryAsync(new(AlbumId:album.Id)));await albums.RenameAsync(album.Id,"Renamed");Assert.Equal("Renamed",(await persistence.GetAlbumAsync(album.Id))!.Name);await albums.SetCoverAsync(album.Id,media.Id);Assert.Equal(media.Id,(await persistence.GetAlbumAsync(album.Id))!.CoverMediaItemId);await albums.RemoveAsync(album.Id,media.Id);Assert.Empty(await persistence.QueryAsync(new(AlbumId:album.Id)));await albums.DeleteAsync(album.Id);Assert.NotNull(await persistence.GetMediaItemAsync(media.Id));}
    [Fact] public async Task ViewerRestoresOriginMovesResetsZoomAndFavorites(){await using TestDatabase db=await TestDatabase.CreateAsync();SqliteGalleryPersistence persistence=new(db.Factory);await SeedAsync(persistence,"a.png","b.png");GalleryMediaItem[] items=(await persistence.QueryAsync(new(SortMode:GallerySortMode.Filename))).ToArray();GalleryViewerSession viewer=new(persistence);await viewer.OpenAsync(items,items[0].Id,1920,1080);Assert.Equal(items[0].Id,viewer.OriginatingItemId);viewer.Zoom(2);Assert.NotEqual(GalleryZoomMode.Fit,viewer.Viewport!.Mode);await viewer.MoveAsync(1,1920,1080);Assert.Equal(GalleryZoomMode.Fit,viewer.Viewport!.Mode);await viewer.ToggleFavoriteAsync();Assert.True((await persistence.GetMediaItemAsync(viewer.Current!.Id))!.Favorite);}
    [Fact] public async Task ApplicationStateAndLaunchPreferencesRoundTrip(){await using TestDatabase db=await TestDatabase.CreateAsync();SqliteGalleryPersistence persistence=new(db.Factory);GalleryApplicationState state=new(GalleryViewKind.Timeline,"item","source","album",GalleryGridSize.Large,GallerySortMode.Filename,"filter",GalleryZoomMode.Fill,7,42);await persistence.SaveApplicationStateAsync(state);Assert.Equal(state,await persistence.GetApplicationStateAsync());GalleryLaunchPreference preference=new("pref",GalleryLaunchPreferenceScope.GlobalVideo,null,"app","--play \"{MEDIA_PATH}\"");await persistence.SaveLaunchPreferenceAsync(preference);Assert.Equal(preference,await persistence.GetLaunchPreferenceAsync(GalleryLaunchPreferenceScope.GlobalVideo,null));}
    [Fact] public async Task QuerySearchesFilenameFolderSourceAndAlbum(){await using TestDatabase db=await TestDatabase.CreateAsync();SqliteGalleryPersistence persistence=new(db.Factory);await SeedAsync(persistence,"holiday-photo.png");GalleryMediaItem media=(await persistence.QueryAsync(new())).Single();DateTime now=DateTime.UtcNow;await persistence.SaveAlbumAsync(new("album","Memories",null,GalleryAlbumType.Manual,null,null,0,now,now));await persistence.AddAlbumItemAsync(new("album",media.Id,0,now));Assert.Single(await persistence.QueryAsync(new(SearchText:"holiday")));Assert.Single(await persistence.QueryAsync(new(SearchText:"Synthetic")));Assert.Single(await persistence.QueryAsync(new(SearchText:"Memories")));}
    [Fact] public async Task FavoriteAndHiddenUpdatesAreIncremental(){await using TestDatabase db=await TestDatabase.CreateAsync();SqliteGalleryPersistence persistence=new(db.Factory);await SeedAsync(persistence);GalleryMediaItem media=(await persistence.QueryAsync(new())).Single();await persistence.SetFavoriteAsync(media.Id,true);Assert.Single(await persistence.QueryAsync(new(FavoritesOnly:true)));await persistence.SetHiddenAsync(media.Id,true);Assert.Empty(await persistence.QueryAsync(new()));Assert.Single(await persistence.QueryAsync(new(IncludeHidden:true)));}

    private static GalleryMediaItem Item(string id)=>new(){Id=id,GallerySourceId="source",MediaType=GalleryMediaType.Image,FilePath=$"C:\\{id}.png",NormalizedFilePath=$"C:\\{id}.png",FileName=id+".png",Extension=".png",ParentFolder="C:\\",FileSize=10,ModifiedAtUtc=DateTime.UtcNow,Width=1600,Height=900,Available=true,AddedAtUtc=DateTime.UtcNow,UpdatedAtUtc=DateTime.UtcNow};
    private static async Task SeedAsync(SqliteGalleryPersistence persistence,params string[] names){if(names.Length==0)names=["image.png"];DateTime now=DateTime.UtcNow;GallerySource source=new(){Id="source",Name="Synthetic",FolderPath="C:\\Synthetic",NormalizedFolderPath="C:\\Synthetic",SourceKind=GallerySourceKind.Photos,CreatedAtUtc=now,UpdatedAtUtc=now};await persistence.AddSourceAsync(source);List<GalleryMediaInspectionResult> values=[];foreach(string name in names){string path=Path.Combine(source.FolderPath,name);values.Add(new(new(path,path,name,".png",source.FolderPath,10,now,now,GalleryMediaType.Image),1600,900));}await persistence.ApplyScanAsync(new(source,values.Select(value=>value.Candidate).ToArray(),[],[],true,false,true,now,now),values);}
    private sealed class NoopLogger:IAppLogger{public void Information(string eventName,string message,IReadOnlyDictionary<string,object?>? properties=null){}public void LogError(string eventName,string message,Exception? exception=null,IReadOnlyDictionary<string,object?>? properties=null){}}
    private sealed class TestDatabase : IAsyncDisposable{private readonly string _root;private TestDatabase(string root,SqliteConnectionFactory factory){_root=root;Factory=factory;}public SqliteConnectionFactory Factory{get;}public static async Task<TestDatabase> CreateAsync(){string root=Path.Combine(Path.GetTempPath(),"NexaStationGalleryExperience",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);SqliteConnectionFactory factory=new(Path.Combine(root,"test.db"));await new DatabaseInitializer(factory,new NoopLogger()).InitializeAsync();return new(root,factory);}public ValueTask DisposeAsync(){Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();try{if(Directory.Exists(_root))Directory.Delete(_root,true);}catch(IOException){}return ValueTask.CompletedTask;}}
}
